<main id="client-photos" class="container pb-5"><p class="pf-gallery-status" data-gallery-loading data-ready="Your photos are ready to download." role="status" aria-live="polite" aria-busy="true"><span class="pf-spinner" aria-hidden="true"></span>Preparing your photos...</p><p class="text-white-50">Tap a photo to preview it. Download photos individually, choose a few, or download the whole gallery below. Multiple photos download together in a ZIP file.</p><form data-download-form method="POST" action="{{ route('delivery.zip',$token) }}">@csrf<div class="final-grid">@foreach($photos as $photo)<article class="final-photo" data-name="{{ $photo->filename }}"><img data-gallery-image class="pf-image-loading" loading="lazy" src="{{ route('delivery.image',[$token,$photo]) }}" alt="{{ $photo->filename }}" onclick="openPreview(this)"><label><input class="choice" type="checkbox" name="photos[]" value="{{ $photo->id }}"> Select</label><span class="filename">{{ $photo->filename }}</span><a data-download-link class="btn btn-light btn-sm" href="{{ route('delivery.download',[$token,$photo]) }}" aria-label="Download {{ $photo->filename }}">Download</a></article>@endforeach</div>{{ $photos->links() }}<div class="delivery-bar d-flex justify-content-between align-items-center mt-4"><b><span id="selected">0</span> photos selected</b><div class="delivery-actions d-flex gap-2"><button type="button" class="btn btn-light" onclick="setAll(true)">Select this page</button><button type="button" class="btn btn-light" onclick="setAll(false)">Clear</button><button class="btn btn-dark" id="download-selected" disabled>Download selected</button></div></div></form><form data-download-form method="POST" action="{{ route('delivery.zip',$token) }}" class="text-center mt-3">@csrf<input type="hidden" name="all" value="1"><button class="btn btn-outline-light btn-lg">Download all photos</button></form></main>
<div class="modal fade" id="preview" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content bg-dark"><div class="modal-header"><a data-download-link id="preview-download" class="btn btn-light">Download</a></div><div class="modal-body text-center p-0"><img id="preview-image" class="img-fluid" style="max-height:88vh" alt=""><div id="preview-name" class="position-absolute bottom-0 start-50 translate-middle-x bg-dark bg-opacity-75 px-3 py-2 rounded-top"></div><button class="preview-nav preview-prev" type="button" onclick="movePreview(-1)" aria-label="Previous photo"><i class="bi bi-chevron-left"></i></button><button class="preview-nav preview-next" type="button" onclick="movePreview(1)" aria-label="Next photo"><i class="bi bi-chevron-right"></i></button><button class="btn-close btn-close-white position-absolute top-0 end-0 m-3" data-bs-dismiss="modal" aria-label="Close"></button></div></div></div></div>
<script src="{{ asset('vendor/bootstrap/bootstrap.bundle.min.js') }}"></script><script>const boxes=[...document.querySelectorAll('.choice')],cards=[...document.querySelectorAll('.final-photo')],count=document.getElementById('selected'),button=document.getElementById('download-selected');let previewIndex=0;function update(){const n=boxes.filter(x=>x.checked).length;count.textContent=n;button.disabled=!n||button.getAttribute('aria-busy')==='true'}boxes.forEach(x=>x.onchange=update);function setAll(value){boxes.forEach(x=>x.checked=value);update()}function displayPreview(){const card=cards[previewIndex],img=card.querySelector('img'),target=document.getElementById('preview-image');target.src=img.src;target.alt=img.alt;document.getElementById('preview-download').href=card.querySelector('a').href;document.getElementById('preview-name').textContent=`${previewIndex+1} / ${cards.length} · ${card.dataset.name}`}function openPreview(img){previewIndex=cards.indexOf(img.closest('.final-photo'));displayPreview();bootstrap.Modal.getOrCreateInstance(document.getElementById('preview')).show()}function movePreview(step){previewIndex=(previewIndex+step+cards.length)%cards.length;displayPreview()}document.addEventListener('keydown',event=>{if(!document.getElementById('preview').classList.contains('show'))return;if(event.key==='ArrowLeft')movePreview(-1);if(event.key==='ArrowRight')movePreview(1)});</script></body></html>
